  \node[anchor=north west, text width=505mm, align=left] at ([xshift=34mm,yshift=-92mm]current page.north west) {\SubFont\color{textmuted} Two centuries of extraordinary progress — and the unfinished work of getting every child into school and learning.};
  \node[anchor=north east, align=right] at ([xshift=-34mm,yshift=-32mm]current page.north east) {\fontsize{16}{20}\selectfont\bfseries\color{secondary} PROGRESS\par\color{accent} GAPS\par\color{cyan} INEQUALITY};
\end{tikzpicture}

\vspace*{166mm}
\hspace*{26mm}\begin{minipage}{542mm}
\begin{minipage}[t]{130mm}\stat{\textcolor{secondary}{\BigNum <1 in 5}}{adults educated}{around 1800}\end{minipage}\hfill
\begin{minipage}[t]{130mm}\stat{\textcolor{secondary}{\BigNum >4 in 5}}{adults educated}{today}\end{minipage}\hfill
