\begin{minipage}[t]{130mm}\stat{\textcolor{cyan}{\BigNum 10+}}{quality years}{in high-income countries}\end{minipage}

\vspace{10mm}
\begin{minipage}[t]{260mm}
\begin{tcolorbox}[amberbox,height=170mm]
\sectiontitle{secondary}{Two centuries of expansion}
\BodyFont\color{textlight}
Education access has been transformed from an elite privilege into a global norm. In the early 1800s, fewer than one in five adults had any formal education. Today, more than four in five adults aged 15+ have received some primary, secondary, or tertiary schooling.
\vspace{7mm}
\begin{tikzpicture}[x=1mm,y=1mm]
  \foreach \i in {0,...,9}{\draw[rounded corners=1.6mm, line width=1.2pt, draw=textmuted, fill=paperbg] (\i*22,50) rectangle ++(13,28);}
  \foreach \i in {0,1}{\draw[rounded corners=1.6mm, line width=1.2pt, draw=secondary, fill=secondary] (\i*22,50) rectangle ++(13,28);}
  \node[anchor=west] at (0,39) {\SmallFont\color{textmuted}1800: fewer than 2 of every 10 adults};
  \foreach \i in {0,...,9}{\draw[rounded corners=1.6mm, line width=1.2pt, draw=secondary, fill=secondary] (\i*22,6) rectangle ++(13,28);}
  \foreach \i in {8,9}{\draw[rounded corners=1.6mm, line width=1.2pt, draw=textmuted, fill=paperbg] (\i*22,6) rectangle ++(13,28);}
  \node[anchor=west] at (0,-5) {\SmallFont\color{textmuted}Today: more than 8 of every 10 adults};
\end{tikzpicture}
\end{tcolorbox}

\vspace{9mm}
\begin{tcolorbox}[coralbox,height=148mm]
\sectiontitle{accent}{Enrollment \(\neq\) learning}
\BodyFont\color{textlight}
School attendance is not the same as learning. In many lower-income countries, fewer than 20\% of children achieve minimum reading proficiency by the end of primary school.
\vspace{8mm}
\begin{tikzpicture}[x=1mm,y=1mm]
  \fill[textmuted!28] (0,0) rectangle (208,20);
  \fill[accent] (0,0) rectangle (41.6,20);
  \draw[white, opacity=.35] (41.6,-3) -- (41.6,25);
  \node[anchor=south west] at (0,27) {\SmallFont\bfseries\color{accent}<20\% reach minimum reading proficiency};
  \node[anchor=north west] at (0,-7) {\SmallFont\color{textmuted}A learning crisis can hide behind enrollment gains.};
\end{tikzpicture}
\end{tcolorbox}

\vspace{9mm}
\begin{tcolorbox}[bluebox,height=112mm]
\sectiontitle{cyan}{Closing the gender gap}
\BodyFont\color{textlight}
Globally, gender gaps in primary and secondary enrollment have nearly closed, and young women now exceed young men in tertiary enrollment.
\vspace{5mm}
{\SmallFont\color{textmuted}\faVenus\ \faMars\ Primary and secondary: near parity globally\par\vspace{2mm}\faGraduationCap\ Tertiary: women now enroll at higher rates\par\vspace{2mm}\textcolor{accent}{Important exception:} girls remain far less likely to attend school in places such as Afghanistan.}
\end{tcolorbox}
\end{minipage}
\hfill
\begin{minipage}[t]{260mm}
\begin{tcolorbox}[hero,height=210mm]
\centering
{\fontsize{30}{36}\selectfont\bfseries\color{accent}The reality check}\par\vspace{4mm}
{\HugeNum\color{accent}244 million}\par\vspace{1mm}
{\fontsize{25}{30}\selectfont\bfseries\color{textlight}children and adolescents were out of school in 2023}\par\vspace{8mm}
\begin{tikzpicture}[x=1mm,y=1mm]
  \fill[accent] (0,0) rectangle (206,28);
  \fill[secondary] (0,35) rectangle (67,28+35);
  \node[anchor=west] at (4,14) {\fontsize{17}{20}\selectfont\bfseries\color{primary}Secondary-age adolescents: ~184M};
  \node[anchor=west] at (4,49) {\fontsize{17}{20}\selectfont\bfseries\color{primary}Primary-age children: ~60M};
  \draw[textmuted, line width=1pt] (0,-8) -- (206,-8);
  \foreach \x/\lab in {0/0,52/60M,103/122M,155/184M,206/244M}{\draw[textmuted] (\x,-11) -- (\x,-5); \node[anchor=north] at (\x,-14) {\TinyFont\color{textmuted}\lab};}
\end{tikzpicture}
\vspace{7mm}
{\BodyFont\color{textlight}Secondary dropout is a major driver: many children complete primary school but do not continue.}
\end{tcolorbox}

\vspace{9mm}
\begin{tcolorbox}[darkbox,height=170mm]
\sectiontitle{secondary}{A world divided by quality schooling}
\BodyFont\color{textlight}
Learning-adjusted years combine time in school with how much students actually learn. The gap is stark: children in the poorest countries receive less than one-third of the quality schooling available in wealthy nations.
\vspace{8mm}
\begin{tikzpicture}[x=1mm,y=1mm]
  \node[anchor=east] at (64,56) {\SmallFont\color{textmuted}Poorest countries};
  \fill[accent] (70,46) rectangle (122,66);
  \node[anchor=west] at (128,56) {\fontsize{25}{28}\selectfont\bfseries\color{accent}<3 years};
  \node[anchor=east] at (64,20) {\SmallFont\color{textmuted}High-income countries};
  \fill[cyan] (70,10) rectangle (244,30);
  \node[anchor=west] at (250,20) {\fontsize{25}{28}\selectfont\bfseries\color{cyan}10+ years};
  \draw[textmuted] (70,0) -- (244,0);
  \foreach \x/\lab in {70/0,122/3,244/10+}{\draw[textmuted] (\x,-3) -- (\x,3); \node[anchor=north] at (\x,-6) {\TinyFont\color{textmuted}\lab};}
\end{tikzpicture}
\end{tcolorbox}

\vspace{9mm}
\begin{tcolorbox}[coralbox,height=50mm]
\centering
{\fontsize{23}{28}\selectfont\bfseries\color{textlight}The story is not progress \emph{or} crisis. It is both.}\par\vspace{2mm}
{\SmallFont\color{textmuted}The next education challenge is closing the gaps between enrollment and learning — and between rich and poor countries.}
\end{tcolorbox}
\end{minipage}

\vspace{9mm}
{\TinyFont\color{textmuted}Sources: UNESCO Institute for Statistics / Global Education Monitoring reporting summarized in the provided brief; learning-adjusted years of schooling estimates for 2020. Values are rounded for public communication.}
\end{minipage}
\end{document}
